#!/usr/bin/env python3
# -*- coding: utf-8 -*-
import base64, zlib, sys, os

if __name__ != "__main__":
    sys.exit(0)

# --- Arabic Terminal Fix (Termux, etc.) ---
try:
    import arabic_reshaper
    from bidi.algorithm import get_display
    _ARABIC_FIX = True
except ImportError:
    _ARABIC_FIX = False

def ar(text):
    if _ARABIC_FIX and isinstance(text, str):
        try:
            return get_display(arabic_reshaper.reshape(text))
        except:
            return text
    return text
# -------------------------------------------

_s = "3HdRwNmEJm8QBZKA3vbj3w=="
_p = ""

_k1 = b"Gh0st1mag3_S3cur3_K3y_2026"
_k2 = base64.b64decode(_s)
_km = _k1 + _k2

_d = base64.b64decode(_p)
_kr = (_km * ((len(_d) // len(_km)) + 1))[:len(_d)]

_c = bytes([a ^ b for a, b in zip(_d, _kr)])
_src = zlib.decompress(_c).decode('utf-8')

_ns = {"__name__": "__main__", "__file__": os.path.abspath(__file__)}
exec(compile(_src, "<ghostimage>", "exec"), _ns)
